await query("CREATE TABLE IF NOT EXISTS inquiries (id SERIAL PRIMARY KEY, character_id INTEGER NOT NULL REFERENCES characters(id), content TEXT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'open', response TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)");
await query("CREATE TABLE IF NOT EXISTS trial_results (run_id VARCHAR(36) NOT NULL, character_id INTEGER NOT NULL REFERENCES characters(id), outcome VARCHAR(16) NOT NULL, finished_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(run_id,character_id))");
await query("CREATE TABLE IF NOT EXISTS server_control (id INTEGER PRIMARY KEY CHECK(id=1), maintenance BOOLEAN NOT NULL, announcement TEXT NOT NULL, schedule TEXT NOT NULL)");
await query('INSERT INTO server_control(id,maintenance,announcement,schedule) VALUES(1,$1,$2,$3) ON CONFLICT(id) DO NOTHING',[process.env.MAINTENANCE==='true',process.env.ANNOUNCEMENT||'',process.env.MAINTENANCE_SCHEDULE||'']);
