const parties=new PartyManager(id=>players.get(id), (id,data)=>{const p=players.get(id);if(p)send(p,data);});
const friends=new Friends(query,id=>players.has(id),(id,data)=>{const p=players.get(id);if(p)send(p,data);});
await friends.init();
const dungeon=new TrialDungeon((id,data)=>{const p=players.get(id);if(p)send(p,data);},async(runId,participants,outcome)=>{for(const id of participants)await query('INSERT INTO trial_results(run_id,character_id,outcome) VALUES($1,$2,$3) ON CONFLICT DO NOTHING',[runId,id,outcome]);});
setInterval(()=>dungeon.cleanup(),1000).unref();
function save(p:Player):Promise<void>{const values=[p.x,p.z,p.level,p.xp,p.hp,p.mp,JSON.stringify(p.inventory),p.id];p.saveQueue=p.saveQueue.then(async()=>{await query('UPDATE characters SET x=$1,z=$2,level=$3,xp=$4,hp=$5,mp=$6,inventory=$7 WHERE id=$8',values);}).catch(e=>{storageErrors++;console.error('저장 실패:',e);notice(p,'저장에 실패했습니다. 서버 상태를 확인하세요.');});return p.saveQueue;}
