 if(req.method==='GET'&&url.pathname==='/api/admin/metrics'){if(!process.env.ADMIN_TOKEN||req.headers.authorization!==`Bearer ${process.env.ADMIN_TOKEN}`)return json(res,403,{error:'접근이 거부되었습니다.'});let databaseAvailable=false;try{await query('SELECT 1');databaseAvailable=true;}catch{}const memory=process.memoryUsage();return json(res,200,{databaseAvailable,dbQueryCount,dbQueryFailures,lastDbFailureAt,lastDbQueryMs,eventLoopP95Ms:Math.round(eventLoopDelay.percentile(95)/1e5)/10,memoryRssBytes:memory.rss,heapUsedBytes:memory.heapUsed,uptimeSeconds:Math.floor(process.uptime())});}
